function studentsPage(){
  const isAdmin=appState.role==='admin';
  let rows=[...appState.students];
  const q=(appState.search||'').toLowerCase().trim();
  if(q) rows=rows.filter(s=>(s.name+' '+s.id+' '+s.nisn+' '+s.major+' '+s.grade+' '+s.email).toLowerCase().includes(q));
  if(appState.searchStatus&&appState.searchStatus!=='all')rows=rows.filter(s=>s.status===appState.searchStatus);
  const action=isAdmin?`<button class="btn" onclick="showStudentModal()">＋ Tambah siswa</button>`:`<button class="btn" onclick="navigate('assessments')">✓ Buka penilaian</button>`;
  return `${dashboardWelcome(isAdmin?'Kelola data siswa':'Daftar siswa penugasan',isAdmin?'Cari, periksa, tambah, dan perbarui data siswa demo.':'Cari peserta yang ditugaskan dan lihat data untuk kebutuhan asesmen.',action)}
    <div class="panel"><div class="filter-row"><div class="filter-left"><input class="filter-input" aria-label="Cari siswa" placeholder="⌕ Cari nama, NISN, kelas..." value="${esc(appState.search)}" oninput="appState.search=this.value;refreshContent()"><select class="filter-select" aria-label="Filter status" onchange="filterStudentStatus(this.value)"><option value="all" ${!appState.searchStatus||appState.searchStatus==='all'?'selected':''}>Semua status</option><option value="Aktif" ${appState.searchStatus==='Aktif'?'selected':''}>Aktif</option><option value="Menunggu" ${appState.searchStatus==='Menunggu'?'selected':''}>Menunggu</option></select></div><div class="filter-right">${isAdmin?`<button class="btn secondary sm" onclick="downloadCsv()">⇩ Ekspor CSV</button><button class="btn secondary sm" onclick="navigate('import')">⇧ Import data</button>`:`<button class="btn secondary sm" onclick="downloadCsv()">⇩ Ekspor CSV demo</button>`}</div></div>
    ${rows.length?studentTable(rows,true,isAdmin):`<div class="empty"><div>⌕</div><b>Data siswa tidak ditemukan</b><p>Coba kata kunci atau status lain.</p><button class="btn secondary sm" onclick="appState.search='';appState.searchStatus='all';refreshContent()">Reset filter</button></div>`}
    <div class="table-footer"><span>Menampilkan <b>${rows.length}</b> dari ${appState.students.length} siswa</span><span>${isAdmin?'Data contoh · mode prototype':'Mode baca untuk guru'}</span></div></div>
    <div class="notice">${isAdmin?'Perubahan data disimpan sementara di sesi browser untuk kebutuhan demonstrasi; tidak ada database.':'Guru dapat melihat siswa dan mengelola penilaian, sedangkan perubahan data identitas dikelola Admin Sekolah.'}</div>`;
}
function filterStudentStatus(v){appState.searchStatus=v;refreshContent()}
function refreshContent(){const el=document.querySelector('.content');if(!el)return;const active=document.activeElement;const focusInfo=active?{id:active.id,aria:active.getAttribute('aria-label'),selectionStart:typeof active.selectionStart==='number'?active.selectionStart:null,selectionEnd:typeof active.selectionEnd==='number'?active.selectionEnd:null}:null;el.innerHTML=pageContent();if(focusInfo){let next=focusInfo.id?document.getElementById(focusInfo.id):null;if(!next&&focusInfo.aria)next=[...el.querySelectorAll('[aria-label]')].find(x=>x.getAttribute('aria-label')===focusInfo.aria);if(next){next.focus({preventScroll:true});if(focusInfo.selectionStart!==null&&typeof next.setSelectionRange==='function'){try{next.setSelectionRange(focusInfo.selectionStart,focusInfo.selectionEnd)}catch(error){}}}}}
function teachersPage(){return `${dashboardWelcome('Data guru','Kelola data guru contoh yang berperan dalam asesmen kompetensi.')}
  <div class="panel"><div class="filter-row"><div class="filter-left"><input class="filter-input" id="teacherSearch" placeholder="⌕ Cari nama, bidang, atau email..." oninput="filterTeachers(this.value)"></div><div class="filter-right"><button class="btn secondary sm" onclick="downloadTeachersCsv()">⇩ Ekspor CSV</button><button class="btn" onclick="showTeacherModal()">＋ Tambah guru</button></div></div><div id="teacherTable">${teacherTable(appState.teachers)}</div><div class="table-footer"><span>${appState.teachers.length} guru terdaftar pada demo</span><span>Data dummy</span></div></div>`}
function teacherTable(rows){return `<div class="table-wrap"><table><thead><tr><th>NAMA GURU</th><th>MATA PELAJARAN</th><th>SISWA DITUGASKAN</th><th>EMAIL</th><th>STATUS</th><th>AKSI</th></tr></thead><tbody>${rows.map(t=>`<tr><td><div class="user-cell"><div class="table-avatar">${esc(initials(t.name))}</div><div><b>${esc(t.name)}</b><small>${esc(t.id)}</small></div></div></td><td>${esc(t.subject)}</td><td>${Number(t.count)||0} siswa</td><td>${esc(t.email)}</td><td><span class="tag ${t.status==='Aktif'?'green':'amber'}">${esc(t.status)}</span></td><td><div class="table-actions"><button class="icon-btn" onclick="toast('Detail guru', '${esc(t.name)} · data demo.')">↗</button><button class="icon-btn" title="Hapus guru" onclick="deleteTeacher('${t.id}')">×</button></div></td></tr>`).join('')}</tbody></table></div>`}
function filterTeachers(q){const el=document.getElementById('teacherTable');if(!el)return;const rows=appState.teachers.filter(t=>(t.name+' '+t.subject+' '+t.email+' '+t.id).toLowerCase().includes(String(q||'').toLowerCase()));el.innerHTML=rows.length?teacherTable(rows):`<div class="empty"><div>⌕</div><b>Guru tidak ditemukan</b><p>Coba nama atau mata pelajaran lain.</p></div>`}
function importPage(){return `${dashboardWelcome('Import data massal','Baca file CSV sungguhan di browser, periksa kesalahan, lalu masukkan baris valid ke data sesi demo.')}
  <div class="page-grid"><section class="panel"><div class="panel-head"><div><h3>Unggah file data</h3><p>Gunakan template CSV Sertikom agar kolom terbaca dengan benar.</p></div><span class="tag">Mode demo</span></div><div class="panel-body">
  <div class="upload-zone" id="uploadZone" ondragover="event.preventDefault();this.classList.add('dragover')" ondragleave="this.classList.remove('dragover')" ondrop="event.preventDefault();this.classList.remove('dragover');handleImportFile(event.dataTransfer.files[0])"><div class="upload-icon">⇧</div><b>Tarik file CSV ke sini atau pilih file</b><p>Format yang dibaca: .csv · Maksimum 10 MB<br>Untuk Excel, pilih <b>Save As → CSV UTF-8</b> terlebih dahulu.</p><label class="btn secondary sm" for="importFile">Pilih file CSV</label><input id="importFile" type="file" accept=".csv,text/csv" onchange="handleImportFile(this.files[0])"><div id="fileStatus" class="small muted" style="margin-top:12px">Belum ada file dipilih</div></div>
  <div class="form-grid" style="margin-top:20px"><div class="field"><label for="importType">Jenis data</label><select id="importType" onchange="revalidateImportType()"><option value="students">Data siswa</option><option value="teachers">Data guru</option></select></div><div class="field"><label>Tahun ajaran</label><select id="importYear"><option>2026/2027</option><option>2025/2026</option></select></div></div>
  <div class="action-row"><button class="btn secondary" onclick="downloadTemplate()">⇩ Unduh template sesuai jenis data</button><button class="btn" id="validateBtn" onclick="simulateValidation()" disabled>Validasi & pratinjau →</button></div><div id="validationResult" aria-live="polite"></div>
  </div></section><aside class="panel"><div class="panel-head"><div><h3>Petunjuk import</h3><p>Ikuti langkah berikut</p></div></div><div class="panel-body"><div class="step-list"><div class="step"><div class="step-num">1</div><div><b>Unduh template</b><p>Pilih template siswa atau guru sesuai jenis data.</p></div></div><div class="step"><div class="step-num">2</div><div><b>Isi data contoh</b><p>Gunakan email dummy dan jangan masukkan data pribadi sungguhan.</p></div></div><div class="step"><div class="step-num">3</div><div><b>Validasi file</b><p>Sistem membaca header, memeriksa kolom wajib, email, dan data duplikat.</p></div></div><div class="step"><div class="step-num">4</div><div><b>Pratinjau lalu konfirmasi</b><p>Hanya baris valid yang ditambahkan ke state browser.</p></div></div></div><div class="notice">Tidak ada data yang dikirim ke server. CSV dibaca lokal di browser. File .xlsx belum dibaca langsung.</div></div></aside></div>`}
async function handleImportFile(file){
  if(!file)return;
  const status=document.getElementById('fileStatus');
  const result=document.getElementById('validationResult');
  if(file.size>10*1024*1024){toast('File terlalu besar','Batas ukuran file demo adalah 10 MB.');return}
  if(!/\.csv$/i.test(file.name)){if(status)status.innerHTML=`<span class="tag amber">Format belum didukung</span> Simpan file Excel sebagai CSV UTF-8 lalu unggah ulang.`;if(result)result.innerHTML='';appState.importPreview=null;return}
  try{
    const text=await file.text();
    const parsed=parseCsvText(text);
    if(!parsed.length||parsed.length<2){toast('File CSV kosong','Tambahkan baris header dan minimal satu baris data.');return}
    appState.importPreview={fileName:file.name,rawText:text,type:document.getElementById('importType')?.value||'students'};
    if(status)status.innerHTML=`<span class="tag green">✓ CSV terbaca</span> <b>${esc(file.name)}</b> <span class="muted">(${Math.max(1,Math.round(file.size/1024))} KB · ${parsed.length-1} baris data)</span>`;
    if(result)result.innerHTML='';
    const btn=document.getElementById('validateBtn');if(btn)btn.disabled=false;
    toast('File CSV siap divalidasi',`${parsed.length-1} baris data terbaca dari file.`);
  }catch(error){appState.importPreview=null;if(status)status.textContent='File tidak dapat dibaca sebagai teks CSV.';toast('Gagal membaca file','Pastikan file disimpan dalam format CSV UTF-8.');}
}
function parseCsvText(text){
  const source=String(text||'').replace(/^\uFEFF/,'');const rows=[];let row=[],cell='',quoted=false;
  let commas=0,semicolons=0,tabs=0,scanQuoted=false;
  for(let i=0;i<source.length;i++){const c=source[i];if(c==='"'){if(scanQuoted&&source[i+1]==='"'){i++}else scanQuoted=!scanQuoted}else if(!scanQuoted&&(c==='\n'||c==='\r'))break;else if(!scanQuoted&&c===',')commas++;else if(!scanQuoted&&c===';')semicolons++;else if(!scanQuoted&&c==='\t')tabs++;}
  const delimiter=semicolons>commas&&semicolons>=tabs?';':tabs>commas&&tabs>semicolons?'\t':',';
  for(let i=0;i<source.length;i++){const c=source[i];if(c==='"'){if(quoted&&source[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===delimiter&&!quoted){row.push(cell.trim());cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&source[i+1]==='\n')i++;row.push(cell.trim());if(row.some(v=>v!==''))rows.push(row);row=[];cell=''}else cell+=c;}
  if(cell!==''||row.length){row.push(cell.trim());if(row.some(v=>v!==''))rows.push(row)}return rows;
}
function normalizeImportHeader(value){return String(value||'').toLowerCase().trim().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/g,'')}
function revalidateImportType(){if(!appState.importPreview)return;appState.importPreview.type=document.getElementById('importType').value;document.getElementById('validationResult').innerHTML='';toast('Jenis data diperbarui','Klik Validasi & pratinjau untuk memeriksa file lagi.')}
function simulateValidation(){
  if(!appState.importPreview){toast('Pilih file terlebih dahulu','Unggah file CSV sebelum menjalankan validasi.');return}
  const p=appState.importPreview; p.type=document.getElementById('importType').value;
  const matrix=parseCsvText(p.rawText);if(matrix.length<2){toast('Tidak ada data','File harus memiliki header dan setidaknya satu baris.');return}
  const headers=matrix[0].map(normalizeImportHeader);const index={};
  const aliases=p.type==='students'?{name:['nama','namalengkap','name'],nisn:['nisn'],email:['email'],major:['programkeahlian','program','jurusan','major'],grade:['kelas','class']}:{name:['nama','namalengkap','name'],email:['email'],subject:['matapelajaran','bidang','subject']};
  Object.keys(aliases).forEach(key=>index[key]=headers.findIndex(h=>aliases[key].includes(h)));
  const missing=Object.entries(index).filter(([k,v])=>v<0).map(([k])=>k);
  const seenEmail=new Set(),seenIdentity=new Set();const existing=p.type==='students'?appState.students:appState.teachers;
  const results=matrix.slice(1).map((cells,idx)=>{
    const get=key=>index[key]>=0?String(cells[index[key]]||'').trim():'';
    const d={name:get('name'),email:get('email')};if(p.type==='students'){d.nisn=get('nisn');d.major=get('major');d.grade=get('grade')}else d.subject=get('subject');
    const errors=[];if(missing.length)errors.push('Kolom wajib tidak ditemukan: '+missing.join(', '));
    if(!d.name)errors.push('Nama wajib diisi');
    if(!d.email||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(d.email))errors.push('Email tidak valid');
    if(p.type==='students'){if(!/^\d{10}$/.test(d.nisn))errors.push('NISN harus 10 digit');if(!d.major)errors.push('Program keahlian wajib diisi');if(!d.grade)errors.push('Kelas wajib diisi')}
    else if(!d.subject)errors.push('Mata pelajaran/bidang wajib diisi');
    const emailKey=d.email.toLowerCase();if(emailKey&&seenEmail.has(emailKey))errors.push('Email duplikat di file');seenEmail.add(emailKey);
    const identityKey=p.type==='students'?d.nisn:emailKey;if(identityKey&&seenIdentity.has(identityKey))errors.push(p.type==='students'?'NISN duplikat di file':'Email duplikat di file');seenIdentity.add(identityKey);
    if(existing.some(x=>(x.email||'').toLowerCase()===emailKey&&emailKey))errors.push('Email sudah terdaftar');
    if(p.type==='students'&&existing.some(x=>x.nisn===d.nisn))errors.push('NISN sudah terdaftar');
    return {line:idx+2,data:d,errors:[...new Set(errors)],valid:errors.length===0};
  });
  p.results=results;p.validRows=results.filter(r=>r.valid);p.errorRows=results.filter(r=>!r.valid);
  renderImportValidation(p);
}
function renderImportValidation(p){
  const total=p.results.length,valid=p.validRows.length,invalid=p.errorRows.length;
  const preview=p.results.slice(0,8);
  document.getElementById('validationResult').innerHTML=`<div class="divider"></div><div class="section-heading"><div><div class="eyebrow">Hasil validasi file</div><h3 style="margin:6px 0 0">Pratinjau data</h3></div><span class="tag ${invalid?'amber':'green'}">${invalid?invalid+' perlu diperbaiki':'Semua data valid'}</span></div>
  <div class="stats-grid import-stats"><div class="stat-card"><div class="stat-name">Total baris</div><div class="stat-value">${total}</div></div><div class="stat-card"><div class="stat-name">Data valid</div><div class="stat-value positive-text">${valid}</div></div><div class="stat-card"><div class="stat-name">Bermasalah</div><div class="stat-value warning-text">${invalid}</div></div></div>
  <div class="table-wrap import-preview"><table><thead><tr><th>BARIS</th><th>NAMA</th><th>EMAIL</th><th>${p.type==='students'?'NISN':'BIDANG'}</th><th>STATUS</th><th>CATATAN</th></tr></thead><tbody>${preview.map(r=>`<tr><td>${r.line}</td><td>${esc(r.data.name)}</td><td>${esc(r.data.email)}</td><td>${esc(p.type==='students'?r.data.nisn:r.data.subject)}</td><td><span class="tag ${r.valid?'green':'red'}">${r.valid?'Valid':'Periksa'}</span></td><td>${esc(r.errors.join('; ')||'Siap diimport')}</td></tr>`).join('')}</tbody></table></div>
  ${total>preview.length?`<p class="small muted">Menampilkan ${preview.length} dari ${total} baris. Semua baris telah divalidasi.</p>`:''}
  <div class="action-row"><button class="btn secondary" onclick="downloadImportErrors()" ${invalid?'':'disabled'}>⇩ Unduh laporan kesalahan</button><button class="btn" onclick="simulateImport()" ${valid?'':'disabled'}>Import ${valid} baris valid →</button></div>
  <div class="notice">Validasi dilakukan di browser. Data hanya ditambahkan ke sesi demo, bukan database. Baris bermasalah tidak ikut diimport.</div>`;
}
function downloadImportErrors(){const p=appState.importPreview;if(!p||!p.errorRows?.length){toast('Tidak ada kesalahan','Semua baris pada file valid.');return}const csv='Baris,Data,Kesalahan\n'+p.errorRows.map(r=>[r.line,JSON.stringify(r.data),r.errors.join('; ')].map(csvEscape).join(',')).join('\n');downloadFile('laporan_kesalahan_import.csv',csv,'text/csv;charset=utf-8');toast('Laporan kesalahan diunduh',`${p.errorRows.length} baris perlu diperbaiki.`)}
function csvEscape(value){return '"'+String(value??'').replace(/"/g,'""')+'"'}

function simulateImport(){
  if(appState.role!=='admin'){toast('Akses terbatas','Import data hanya tersedia untuk Admin Sekolah.');return}
  const p=appState.importPreview;if(!p||!p.validRows||!p.validRows.length){toast('Tidak ada data valid','Lakukan validasi dan perbaiki kesalahan terlebih dahulu.');return}
  let added=0;
  p.validRows.forEach((r)=>{const d=r.data;if(p.type==='students'){appState.students.push({id:'SRT-'+String(appState.students.length+1).padStart(3,'0'),name:d.name,nisn:d.nisn,major:d.major,grade:d.grade,status:'Aktif',email:d.email,score:0,cert:'Belum tersedia'});}else{appState.teachers.push({id:'GR-'+String(appState.teachers.length+1).padStart(3,'0'),name:d.name,email:d.email,subject:d.subject,count:0,status:'Aktif'});}added++;});
  const kind=p.type==='students'?'siswa':'guru';recordActivity('Import data '+kind,`${added} baris valid diimpor dari ${p.fileName}.`);appState.importPreview=null;closeModal();appState.activePage=p.type==='students'?'students':'teachers';appState.search='';saveDemoState();render();toast('Import demo berhasil',`${added} data ${kind} masuk ke daftar untuk sesi ini.`);
}
function downloadTemplate(){const type=document.getElementById('importType')?.value||'students';const csv=type==='students'?'nama,nisn,email,program_keahlian,kelas\nContoh Siswa,0061000001,siswa.import@example.test,Rekayasa Perangkat Lunak,XII RPL 1\n':'nama,email,mata_pelajaran\nContoh Guru,guru.import@example.test,Pemrograman Web\n';downloadFile(type==='students'?'template_import_siswa_sertikom.csv':'template_import_guru_sertikom.csv','\uFEFF'+csv,'text/csv;charset=utf-8');toast('Template diunduh',`Template ${type==='students'?'siswa':'guru'} siap diisi.`)}
function downloadCsv(){const rows=appState.students;const csv='ID,Nama,NISN,Email,Program,Kelas,Status,Nilai\n'+rows.map(s=>[s.id,s.name,s.nisn,s.email,s.major,s.grade,s.status,s.score].map(csvEscape).join(',')).join('\n');downloadFile('data_siswa_dummy_sertikom.csv','\uFEFF'+csv,'text/csv;charset=utf-8');toast('Ekspor data selesai',`${rows.length} baris siswa diekspor sebagai CSV.`)}
function downloadTeachersCsv(){const csv='ID,Nama,Email,Mata Pelajaran,Siswa Ditugaskan,Status\n'+appState.teachers.map(t=>[t.id,t.name,t.email,t.subject,t.count,t.status].map(csvEscape).join(',')).join('\n');downloadFile('data_guru_dummy_sertikom.csv','\uFEFF'+csv,'text/csv;charset=utf-8');toast('Ekspor data selesai',`${appState.teachers.length} baris guru diekspor sebagai CSV.`)}
function downloadFile(name,content,type){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function industryPage(){const invited=appState.invitations.length;const verified=appState.industries.filter(x=>x.status==='Terverifikasi').length+appState.invitations.filter(x=>x.status==='Terverifikasi').length;const pending=appState.industries.filter(x=>x.status!=='Terverifikasi').length+appState.invitations.filter(x=>x.status==='Pendaftaran masuk').length;return `${dashboardWelcome('Mitra industri','Kelola mitra terhubung, tinjau pendaftaran, dan buat tautan undangan demo.',`<button class="btn" onclick="showInviteModal()">＋ Undang mitra</button>`)}<div class="stats-grid">${statCard('Total mitra',String(appState.industries.length+invited).padStart(2,'0'),'▣','Mitra dan undangan demo')}${statCard('Terverifikasi',String(verified).padStart(2,'0'),'✓','Mitra berstatus aktif')}${statCard('Menunggu persetujuan',String(pending).padStart(2,'0'),'◷','Termasuk pendaftaran baru')}${statCard('Undangan dibuat',String(invited).padStart(2,'0'),'✉','Tautan sesi demo')}</div><div class="panel"><div class="filter-row"><div><b style="font-size:13px">Daftar mitra industri</b><div class="small muted" style="margin-top:4px">Alur undangan → pendaftaran demo → persetujuan</div></div><div class="filter-right"><input class="filter-input" placeholder="⌕ Cari mitra..." oninput="filterIndustry(this.value)"><button class="btn secondary sm" onclick="downloadIndustryCsv()">⇩ Ekspor CSV</button></div></div><div id="industryTable">${industryTable([...appState.industries,...appState.invitations])}</div></div><div class="notice">Tautan dan pendaftaran mitra hanya simulasi lokal. Tidak ada email atau WhatsApp yang dikirim.</div>`}
function industryTable(rows){return `<div class="table-wrap"><table><thead><tr><th>NAMA MITRA</th><th>BIDANG</th><th>KONTAK</th><th>EMAIL</th><th>STATUS</th><th>AKSI</th></tr></thead><tbody>${rows.map(x=>{const invite=String(x.id||'').startsWith('INV-');const statusClass=x.status==='Terverifikasi'?'green':x.status==='Ditolak'?'red':'amber';return `<tr><td><div class="user-cell"><div class="table-avatar">${initials(x.name)}</div><div><b>${esc(x.name)}</b><small>${esc(x.access||(invite?'Undangan dibuat':'Mitra sekolah'))}</small></div></div></td><td>${esc(x.sector)}</td><td>${esc(x.contact||'—')}</td><td>${esc(x.email)}</td><td><span class="tag ${statusClass}">${esc(x.status||'Undangan dibuat')}</span></td><td><div class="table-actions"><button class="icon-btn" title="Detail" onclick="showIndustryDetail('${esc(x.email)}')">↗</button>${invite?`<button class="icon-btn" title="Simulasikan pendaftaran" onclick="showInviteRegistration('${esc(x.id)}')">♙</button><button class="icon-btn" title="Lihat tautan undangan" onclick="copyInvitationByEmail('${esc(x.email)}')">⧉</button>${x.status==='Pendaftaran masuk'?`<button class="icon-btn" title="Setujui mitra" onclick="approveInvitation('${esc(x.email)}')">✓</button><button class="icon-btn" title="Tolak pendaftaran" onclick="rejectInvitation('${esc(x.email)}')">×</button>`:''}`:''}</div></td></tr>`}).join('')}</tbody></table></div>`}
function filterIndustry(q){const el=document.getElementById('industryTable');if(!el)return;const rows=[...appState.industries,...appState.invitations].filter(x=>(x.name+' '+x.sector+' '+(x.contact||'')+' '+x.email).toLowerCase().includes(String(q||'').toLowerCase()));el.innerHTML=rows.length?industryTable(rows):`<div class="empty"><div>⌕</div><b>Mitra tidak ditemukan</b><p>Coba kata kunci yang berbeda.</p></div>`}
function showInviteModal(email=''){openModal('Undang mitra industri',`<form id="inviteForm"><div class="field"><label>Nama perusahaan</label><input name="company" required placeholder="Contoh: PT Teknologi Maju"></div><div class="field"><label>Nama perwakilan (opsional)</label><input name="contact" placeholder="Nama PIC industri"></div><div class="field"><label>Email perwakilan</label><input name="email" type="email" required placeholder="nama@perusahaan.co.id" value="${esc(email)}"></div><div class="field"><label>Bidang industri</label><select name="sector"><option>Teknologi Informasi</option><option>Desain & Kreatif</option><option>Infrastruktur Jaringan</option><option>Manufaktur</option><option>Lainnya</option></select></div><div class="notice">Tautan dibuat untuk demonstrasi saja. Tidak ada email atau WhatsApp yang dikirim.</div></form>`,`<button class="btn secondary" onclick="closeModal()">Batal</button><button class="btn" onclick="createInvite()">Buat tautan demo</button>`)}
function createInvite(){if(appState.role!=='admin'){toast('Akses terbatas','Hanya Admin Sekolah yang dapat mengundang mitra.');return}const f=document.getElementById('inviteForm');if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f));if([...appState.industries,...appState.invitations].some(x=>String(x.email||'').toLowerCase()===d.email.toLowerCase())){toast('Email sudah terdaftar','Gunakan email mitra demo yang berbeda.');return}const token=Math.random().toString(36).slice(2,9).toUpperCase();const url=`demo.sertikom.local/invite/${token}`;const row={id:'INV-'+token,name:d.company,email:d.email,sector:d.sector,contact:d.contact||'Belum diisi',status:'Menunggu',access:'Undangan terkirim',url,token,createdAt:new Date().toLocaleDateString('id-ID')};appState.invitations.unshift(row);recordActivity('Undangan mitra dibuat',`${d.company} · ${d.email}`);saveDemoState();closeModal();openModal('Undangan berhasil dibuat',`<div class="info-card"><h3>${esc(d.company)}</h3><p>${esc(d.email)} · ${esc(d.sector)}</p><div class="field"><label>Tautan undangan (contoh)</label><input id="inviteUrl" value="${esc(url)}" readonly></div><span class="tag green">● Tersimpan di sesi demo</span><p style="margin-top:12px">Tautan tidak membuka pendaftaran sungguhan. Untuk presentasi, gunakan tombol simulasi pendaftaran di bawah ini.</p></div>`,`<button class="btn secondary" onclick="closeModal();navigate('industry')">Lihat daftar mitra</button><button class="btn secondary" onclick="showInviteRegistration('${esc(row.id)}')">Simulasikan pendaftaran</button><button class="btn" onclick="copyInvite()">Salin tautan</button>`)}
function showInviteRegistration(id){const x=appState.invitations.find(i=>i.id===id);if(!x){toast('Undangan tidak ditemukan','Tautan ini tidak ada dalam sesi demo.');return}if(x.status==='Terverifikasi'){toast('Mitra sudah aktif',x.name+' telah disetujui pada sesi demo.');return}openModal('Pendaftaran dari undangan industri',`<div class="notice">Formulir ini menirukan proses ketika perwakilan industri membuka tautan undangan.</div><form id="inviteRegistrationForm"><div class="field"><label>Nama perusahaan</label><input value="${esc(x.name)}" readonly></div><div class="field"><label>Email terundang</label><input value="${esc(x.email)}" readonly></div><div class="field"><label>Nama perwakilan</label><input name="contact" required value="${esc(x.contact==='Belum diisi'?'':x.contact)}" placeholder="Nama PIC industri"></div><div class="field"><label>Bidang industri</label><input value="${esc(x.sector)}" readonly></div><p class="small muted">Setelah dikirim, status akan menjadi “Pendaftaran masuk” dan Admin dapat menyetujui atau menolak mitra.</p></form>`,`<button class="btn secondary" onclick="closeModal()">Batal</button><button class="btn" onclick="acceptInvite('${esc(x.id)}')">Kirim pendaftaran demo</button>`)}
function acceptInvite(id){const f=document.getElementById('inviteRegistrationForm');if(!f.reportValidity())return;const x=appState.invitations.find(i=>i.id===id);if(!x)return;const d=Object.fromEntries(new FormData(f));x.contact=d.contact;x.status='Pendaftaran masuk';x.access='Menunggu verifikasi';x.registeredAt=new Date().toLocaleDateString('id-ID');recordActivity('Pendaftaran mitra diterima',`${x.name} · menunggu persetujuan`);saveDemoState();closeModal();appState.activePage='industry';render();toast('Pendaftaran mitra diterima (demo)',`${x.name} sekarang menunggu persetujuan Admin.`)}
function copyInvite(){const el=document.getElementById('inviteUrl');if(!el)return;el.select();el.setSelectionRange(0,99999);if(navigator.clipboard&&window.isSecureContext){navigator.clipboard.writeText(el.value).then(()=>toast('Tautan demo disalin','Tautan dapat ditempelkan ke catatan presentasi.')).catch(()=>toast('Pilih tautan untuk menyalin','Browser menolak akses clipboard; salin secara manual.'))}else{try{const ok=document.execCommand('copy');toast(ok?'Tautan demo disalin':'Pilih tautan untuk menyalin',ok?'Tautan siap ditempelkan.':'Salin tautan secara manual.')}catch(e){toast('Pilih tautan untuk menyalin','Salin tautan secara manual.')}}}

function showIndustryDetail(email){const x=[...appState.industries,...appState.invitations].find(i=>i.email===email);if(!x)return;const invite=String(x.id||'').startsWith('INV-');let footer='<button class="btn secondary" onclick="closeModal()">Tutup</button>';if(invite&&x.status==='Pendaftaran masuk')footer+=`<button class="btn secondary" onclick="rejectInvitation('${esc(x.email)}')">Tolak</button><button class="btn" onclick="approveInvitation('${esc(x.email)}')">Setujui mitra</button>`;else if(invite&&x.status!=='Terverifikasi'&&x.status!=='Ditolak')footer+=`<button class="btn" onclick="showInviteRegistration('${esc(x.id)}')">Simulasikan pendaftaran</button>`;openModal('Detail mitra industri',`<div class="profile-details" style="margin-top:0"><div class="detail-box"><span>Nama perusahaan</span><b>${esc(x.name)}</b></div><div class="detail-box"><span>Bidang</span><b>${esc(x.sector)}</b></div><div class="detail-box"><span>Kontak</span><b>${esc(x.contact||'Belum diisi')}</b></div><div class="detail-box"><span>Email</span><b>${esc(x.email)}</b></div><div class="detail-box"><span>Status</span><b>${esc(x.status||'Undangan dibuat')}</b></div><div class="detail-box"><span>Informasi tautan</span><b>${esc(x.url||'Mitra sudah terdaftar')}</b></div></div>`,footer)}
function approveInvitation(email){if(appState.role!=='admin'){toast('Akses terbatas','Persetujuan mitra hanya tersedia untuk Admin Sekolah.');return}const x=appState.invitations.find(i=>i.email===email);if(!x){toast('Mitra tidak ditemukan');return}if(x.status!=='Pendaftaran masuk'){toast('Belum ada pendaftaran','Mitra harus menyelesaikan simulasi pendaftaran sebelum disetujui.');return}x.status='Terverifikasi';x.access='Mitra aktif';recordActivity('Mitra disetujui',x.name);saveDemoState();closeModal();render();toast('Mitra disetujui (demo)',x.name+' kini berstatus terverifikasi pada sesi ini.')}
function rejectInvitation(email){if(appState.role!=='admin'){toast('Akses terbatas','Pengelolaan mitra hanya tersedia untuk Admin Sekolah.');return}const x=appState.invitations.find(i=>i.email===email);if(!x){toast('Mitra tidak ditemukan');return}x.status='Ditolak';x.access='Pendaftaran ditolak';recordActivity('Pendaftaran mitra ditolak',x.name);saveDemoState();closeModal();render();toast('Pendaftaran ditolak (demo)',x.name+' ditandai ditolak pada sesi ini.')}
function copyInvitationByEmail(email){const x=appState.invitations.find(i=>i.email===email);if(!x){toast('Tidak ada tautan undangan','Mitra ini tidak dibuat melalui undangan sesi demo.');return}openModal('Tautan undangan',`<div class="field"><label>Tautan demo</label><input id="inviteUrl" readonly value="${esc(x.url)}"></div>`,`<button class="btn secondary" onclick="closeModal()">Tutup</button><button class="btn" onclick="copyInvite()">Salin tautan</button>`)}
function downloadIndustryCsv(){const rows=[...appState.industries,...appState.invitations];const csv='Nama Mitra,Bidang,Kontak,Email,Status\n'+rows.map(x=>[x.name,x.sector,x.contact||'',x.email,x.status||'Undangan dibuat'].map(csvEscape).join(',')).join('\n');downloadFile('daftar_mitra_sertikom.csv','\uFEFF'+csv,'text/csv;charset=utf-8');toast('Ekspor data selesai',`${rows.length} mitra/undangan diekspor.`)}
function certificationPage(){const isAdmin=appState.role==='admin';const title=isAdmin?'Sertifikasi & jadwal':'Jadwal asesmen';return `${dashboardWelcome(title,isAdmin?'Susun agenda, lihat kuota, dan pantau jadwal sertifikasi.':'Lihat agenda asesmen dan persiapkan peserta.',isAdmin?`<button class="btn" onclick="showScheduleModal()">＋ Tambah jadwal</button>`:'')}<div class="stats-grid">${statCard('Program terjadwal',String(appState.schedules.length).padStart(2,'0'),'✦','Agenda pada demo')}${statCard('Agenda mendatang',String(appState.schedules.filter(s=>s.status!=='Selesai').length).padStart(2,'0'),'▦','Belum ditandai selesai')}${statCard('Peserta pada jadwal',String(appState.schedules.reduce((n,s)=>n+Number(s.quota||0),0)),'♙','Total kuota contoh')}${statCard('Selesai',String(appState.schedules.filter(s=>s.status==='Selesai').length).padStart(2,'0'),'✓','Status jadwal')}</div><div class="panel"><div class="panel-head"><div><h3>Jadwal sertifikasi</h3><p>${isAdmin?'Gunakan aksi untuk melihat detail atau mengubah status jadwal demo.':'Jadwal untuk pengawasan dan persiapan asesmen.'}</p></div><span class="tag">Data sesi demo</span></div><div class="table-wrap"><table><thead><tr><th>NAMA PROGRAM</th><th>TANGGAL & WAKTU</th><th>LOKASI</th><th>KUOTA</th><th>STATUS</th><th>AKSI</th></tr></thead><tbody>${appState.schedules.map((s,i)=>`<tr><td><b>${esc(s.title)}</b><div class="small muted" style="margin-top:4px">${esc(s.kind)}</div></td><td>${esc(s.date)}<div class="small muted" style="margin-top:4px">${esc(s.time)}</div></td><td>${esc(s.place)}</td><td>${Number(s.quota||[32,28,21][i]||30)} peserta</td><td><span class="tag ${s.status==='Pendaftaran'?'amber':s.status==='Selesai'?'gray':'green'}">${esc(s.status)}</span></td><td><div class="table-actions"><button class="icon-btn" title="Detail" onclick="showScheduleDetail(${i})">↗</button>${isAdmin?`<button class="icon-btn" title="Ubah status" onclick="toggleScheduleStatus(${i})">✓</button>`:''}</div></td></tr>`).join('')}</tbody></table></div></div><div class="notice">Jadwal adalah data contoh. ${isAdmin?'Perubahan status hanya terjadi di sesi browser ini.':'Guru melihat jadwal dalam mode baca.'}</div>`}
function showScheduleDetail(index){const s=appState.schedules[index];if(!s)return;const footer=appState.role==='admin'?`<button class="btn secondary" onclick="closeModal()">Tutup</button><button class="btn" onclick="closeModal();toggleScheduleStatus(${index})">Ubah status</button>`:`<button class="btn secondary" onclick="closeModal()">Tutup</button>`;openModal('Detail jadwal sertifikasi',`<div class="profile-details" style="margin-top:0"><div class="detail-box"><span>Program</span><b>${esc(s.title)}</b></div><div class="detail-box"><span>Bidang</span><b>${esc(s.kind)}</b></div><div class="detail-box"><span>Tanggal</span><b>${esc(s.date)}</b></div><div class="detail-box"><span>Waktu</span><b>${esc(s.time)}</b></div><div class="detail-box"><span>Lokasi</span><b>${esc(s.place)}</b></div><div class="detail-box"><span>Kuota</span><b>${Number(s.quota||30)} peserta</b></div></div>`,footer)}
function toggleScheduleStatus(index){if(appState.role!=='admin'){toast('Mode baca saja','Perubahan status jadwal hanya tersedia untuk Admin Sekolah.');return}const s=appState.schedules[index];if(!s)return;s.status=s.status==='Selesai'?'Terjadwal':'Selesai';recordActivity('Status jadwal diubah',`${s.title} · ${s.status}`);saveDemoState();render();toast('Status jadwal diperbarui',`${s.title}: ${s.status}.`)}
function showScheduleModal(){if(appState.role!=='admin'){toast('Akses terbatas','Hanya Admin Sekolah yang dapat membuat jadwal.');return}openModal('Tambah jadwal sertifikasi',`<form id="scheduleForm"><div class="field"><label>Nama program</label><input name="title" required placeholder="Nama program sertifikasi"></div><div class="form-grid"><div class="field"><label>Tanggal</label><input name="date" type="date" required></div><div class="field"><label>Waktu</label><input name="time" placeholder="08.00–12.00 WIB" required></div></div><div class="form-grid"><div class="field"><label>Lokasi</label><input name="place" required placeholder="Lab / ruang asesmen"></div><div class="field"><label>Kuota peserta</label><input name="quota" type="number" min="1" value="30" required></div></div><div class="field"><label>Jenis kompetensi</label><select name="kind"><option>Kompetensi Teknis</option><option>Kompetensi Kreatif</option><option>Kompetensi Industri</option></select></div></form>`,`<button class="btn secondary" onclick="closeModal()">Batal</button><button class="btn" onclick="saveSchedule()">Simpan jadwal demo</button>`)}
function saveSchedule(){if(appState.role!=='admin'){toast('Akses terbatas','Hanya Admin Sekolah yang dapat membuat jadwal.');return}const f=document.getElementById('scheduleForm');if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f));const dt=new Date(d.date+'T00:00:00');const dateLabel=Number.isNaN(dt.getTime())?d.date:dt.toLocaleDateString('id-ID',{day:'2-digit',month:'short',year:'numeric'});appState.schedules.unshift({id:'JDL-'+String(appState.schedules.length+1).padStart(3,'0'),title:d.title,date:dateLabel,dateIso:d.date,time:d.time,place:d.place,quota:Number(d.quota),kind:d.kind,status:'Terjadwal'});recordActivity('Jadwal sertifikasi ditambahkan',d.title);closeModal();saveDemoState();appState.activePage='certification';render();toast('Jadwal ditambahkan',`${d.title} tersedia pada sesi demo.`)}
function reportsPage(){
  const total=appState.students.length;
  const scored=appState.students.filter(s=>Number(s.score)>0);
  const competent=appState.students.filter(s=>Number(s.score)>=75).length;
  const certificates=appState.students.filter(s=>s.cert==='Terverifikasi'&&Number(s.score)>=75).length;
  const average=averageStudentScore(scored);
  const verified=appState.industries.filter(x=>x.status==='Terverifikasi').length+appState.invitations.filter(x=>x.status==='Terverifikasi').length;
  const competencyRate=total?Math.round(competent/total*100):0;
  const reinforce=total?Math.round(appState.students.filter(s=>Number(s.score)>0&&Number(s.score)<75).length/total*100):0;
  const pending=total?Math.max(0,100-competencyRate-reinforce):0;
  return `${dashboardWelcome('Laporan & analitik','Ringkasan capaian dihitung dari data dummy yang berubah selama sesi demo.')}
    <div class="stats-grid">${statCard('Data peserta',String(total),'♙','Data pada sesi ini')}${statCard('Sertifikat tersedia',String(certificates),'♜','Status demo terverifikasi')}${statCard('Rata-rata nilai',average?average.toFixed(1).replace('.',','):'—','◷',scored.length+' siswa telah dinilai')}${statCard('Mitra terverifikasi',String(verified).padStart(2,'0'),'▣','Relasi demo aktif')}</div>
    <div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h3>Distribusi hasil</h3><p>Persentase berdasarkan nilai siswa saat ini</p></div><span class="tag">${total} siswa</span></div><div class="panel-body"><div class="progress-item"><div class="progress-label"><b>Kompeten (nilai ≥ 75)</b><span>${competencyRate}%</span></div><div class="progress-track"><i style="width:${competencyRate}%"></i></div></div><div class="progress-item"><div class="progress-label"><b>Perlu penguatan</b><span>${reinforce}%</span></div><div class="progress-track"><i style="width:${reinforce}%;background:#f59e0b"></i></div></div><div class="progress-item"><div class="progress-label"><b>Belum dinilai</b><span>${pending}%</span></div><div class="progress-track"><i style="width:${pending}%;background:#94a3b8"></i></div></div><div class="divider"></div><button class="btn secondary" style="width:100%" onclick="downloadCsv()">⇩ Unduh data siswa CSV</button></div></section>
    <section class="panel"><div class="panel-head"><div><h3>Aktivitas terbaru</h3><p>Aksi yang dilakukan selama sesi demo</p></div></div><div class="panel-body">${activities(demoActivityRows([['⇧','Data dummy dimuat','Data contoh siap digunakan.','Awal sesi']]))}</div></section></div>
    <section class="panel"><div class="panel-head"><div><h3>Rekap nilai siswa</h3><p>Daftar singkat hasil asesmen dari data dummy</p></div><button class="btn secondary sm" onclick="navigate('students')">Lihat semua siswa</button></div><div class="table-wrap"><table><thead><tr><th>NAMA SISWA</th><th>PROGRAM</th><th>NILAI</th><th>STATUS KOMPETENSI</th><th>SERTIFIKAT</th></tr></thead><tbody>${appState.students.map(s=>`<tr><td><b>${esc(s.name)}</b><div class="small muted">${esc(s.id)}</div></td><td>${esc(s.major)}</td><td>${Number(s.score)>0?Number(s.score)+'/100':'—'}</td><td><span class="tag ${Number(s.score)>=75?'green':Number(s.score)>0?'amber':'gray'}">${Number(s.score)>=75?'Kompeten':Number(s.score)>0?'Perlu penguatan':'Belum dinilai'}</span></td><td>${esc(s.cert||'Belum tersedia')}</td></tr>`).join('')}</tbody></table></div></section>
    <div class="notice">Laporan dihitung dari data dummy sesi ini. Tidak ada laporan yang dikirim atau disimpan di server.</div>`;
}
function profilePage(){const u=appState.user;const isAdmin=appState.role==='admin';const school=u.newSchool||'SMK Teknologi Nusantara';return `${dashboardWelcome(isAdmin?'Profil sekolah':'Profil '+activeRole().name,'Kelola informasi yang tampil di ruang kerja demo.')}
  <div class="page-grid"><section class="panel"><div class="panel-head"><div><h3>${isAdmin?'Informasi sekolah':'Informasi profil'}</h3><p>Data contoh · hanya tersimpan selama sesi demo</p></div><button class="btn secondary sm" onclick="showProfileModal()">✎ Edit profil</button></div><div class="panel-body"><div class="profile-card"><div class="profile-large">${isAdmin?'SMK':initials(school)}</div><h3>${esc(isAdmin?school:u.name)}</h3><p>${isAdmin?'NPSN '+(u.npsn||'20201234'):esc(activeRole().name)}</p><div style="margin-top:13px"><span class="tag green">● ${isAdmin?'Profil demo aktif':'Akun demo aktif'}</span></div><div class="profile-details"><div class="detail-box"><span>${isAdmin?'Email Admin':'Email'}</span><b>${esc(u.email)}</b></div><div class="detail-box"><span>${isAdmin?'NPSN':'Username'}</span><b>${esc(isAdmin?(u.npsn||'20201234'):u.username)}</b></div><div class="detail-box"><span>${isAdmin?'Alamat':'Sekolah / Organisasi'}</span><b>${esc(isAdmin?(u.address||'Jl. Pendidikan No. 10, Bogor'):activeRole().school)}</b></div><div class="detail-box"><span>Peran</span><b>${esc(activeRole().name)}</b></div></div></div></div></section>
  <aside class="panel"><div class="panel-head"><div><h3>Preferensi akun</h3><p>Kontrol untuk demonstrasi</p></div></div><div class="panel-body"><div class="activity-list"><div class="activity-item"><span class="activity-icon">♙</span><div style="flex:1"><b>Informasi akun</b><p>Perbarui nama dan email demo.</p></div><button class="link-btn" onclick="showProfileModal()">Edit</button></div><div class="activity-item"><span class="activity-icon">♢</span><div style="flex:1"><b>Keamanan password</b><p>Simulasikan perubahan password akun.</p></div><button class="link-btn" onclick="showPasswordModal(false)">Ubah</button></div><div class="activity-item"><span class="activity-icon">▣</span><div style="flex:1"><b>Mode prototype</b><p>Semua data dummy, tanpa database.</p></div><span class="tag gray">Dummy</span></div></div><div class="divider"></div><div class="info-card"><h3>Mode prototype</h3><p>Semua informasi akun dan data Sertikom pada halaman ini merupakan data dummy, tanpa database.</p><span class="tag gray">Mode demonstrasi</span></div>${isAdmin?`<div class="divider"></div><div class="info-card"><h3>Reset data demonstrasi</h3><p>Mengembalikan siswa, guru, mitra, jadwal, materi, kolaborasi, dan penilaian ke data contoh awal.</p><button class="btn danger" onclick="confirmResetDemo()">Reset semua data demo</button></div>`:''}</div></aside></div>`}
function showProfileModal(){let isAdmin=appState.role==='admin';openModal('Edit '+(isAdmin?'profil sekolah':'profil akun'),`<form id="profileForm"><div class="field"><label>${isAdmin?'Nama sekolah':'Nama lengkap'}</label><input name="name" required value="${esc(isAdmin?(appState.user.newSchool||'SMK Teknologi Nusantara'):appState.user.name)}"></div><div class="field"><label>Email</label><input type="email" name="email" required value="${esc(appState.user.email)}"></div>${isAdmin?`<div class="field"><label>NPSN</label><input name="npsn" pattern="[0-9]{8}" title="NPSN harus 8 digit angka" maxlength="8" value="${esc(appState.user.npsn||'20201234')}"></div><div class="field"><label>Alamat</label><textarea name="address">${esc(appState.user.address||'Jl. Pendidikan No. 10, Bogor')}</textarea></div>`:''}</form>`,`<button class="btn secondary" onclick="closeModal()">Batal</button><button class="btn" onclick="saveProfile()">Simpan perubahan</button>`)}
function saveProfile(){const f=document.getElementById('profileForm');if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f));if(appState.role==='admin'){appState.user.newSchool=d.name;appState.user.npsn=d.npsn;appState.user.address=d.address}else appState.user.name=d.name;appState.user.email=d.email;appState.user.initial=initials(appState.user.name);recordActivity('Profil diperbarui',d.name);closeModal();render();toast('Profil diperbarui','Perubahan profil tersimpan sementara pada sesi demo.')}
function enrollmentTable(rows){
  return `<div class="table-wrap"><table><thead><tr><th>SISWA</th><th>PROGRAM</th><th>TANGGAL DAFTAR</th><th>SUMBER</th><th>PROGRES</th><th>STATUS</th><th>AKSI</th></tr></thead><tbody>${rows.map(e=>{
    const cls=e.status==='Aktif'||e.status==='Selesai'?'status-success':e.status==='Ditolak'?'status-danger':'status-pending';
    return `<tr><td><div class="user-cell"><div class="table-avatar">${initials(e.student)}</div><div><b>${esc(e.student)}</b><small>${esc(e.studentId)}</small></div></div></td><td><b>${esc(e.program)}</b><small class="table-sub">${esc(e.programId)}</small></td><td>${esc(e.date)}</td><td>${esc(e.source||'Demo')}</td><td><div class="mini-progress"><i style="width:${Number(e.progress||0)}%"></i></div><small>${Number(e.progress||0)}%</small></td><td><span class="status-tag ${cls}">${esc(e.status)}</span></td><td><div class="table-actions"><button class="icon-button" title="Detail pendaftaran" onclick="showEnrollmentDetail('${e.id}')">${uiIcon('eye')}</button>${e.status==='Menunggu Verifikasi'?`<button class="icon-button" title="Setujui" onclick="approveEnrollment('${e.id}')">${uiIcon('check')}</button>`:''}<button class="icon-button danger" title="Hapus pendaftaran" onclick="deleteEnrollment('${e.id}')">${uiIcon('trash')}</button></div></td></tr>`
  }).join('')}</tbody></table></div>`
}
function filterEnrollments(){
  const el=document.getElementById('enrollmentTable');if(!el)return;
  const q=(document.getElementById('enrollmentSearch')?.value||'').toLowerCase();
  const st=document.getElementById('enrollmentStatus')?.value||'all';
  const rows=appState.enrollments.filter(e=>(e.student+' '+e.program+' '+e.studentId+' '+e.programId).toLowerCase().includes(q)&&(st==='all'||e.status===st));
  el.innerHTML=rows.length?enrollmentTable(rows):'<div class="empty"><b>Tidak ada pendaftaran</b><p>Ubah kata kunci atau status filter.</p></div>'
}
function enrollmentsPage(){
  const pending=appState.enrollments.filter(e=>e.status==='Menunggu Verifikasi').length;
  const active=appState.enrollments.filter(e=>e.status==='Aktif').length;
  const done=appState.enrollments.filter(e=>e.status==='Selesai').length;
  return `${dashboardWelcome('Pendaftaran peserta','Verifikasi pendaftaran program, pantau progres, dan kelola peserta demo.',`<button class="btn btn-primary" onclick="navigate('programs')">${uiIcon('plus')} Buka katalog</button>`)}<div class="stats-grid">${statCard('Total Pendaftaran',String(appState.enrollments.length),'♟','Seluruh pendaftaran')}${statCard('Menunggu Verifikasi',String(pending),'◷','Perlu ditinjau')}${statCard('Sedang Aktif',String(active),'▣','Peserta berjalan')}${statCard('Selesai',String(done),'✓','Program tuntas')}</div><div class="panel"><div class="panel-head"><div><h3>Daftar pendaftaran</h3><p>Setujui peserta baru atau tinjau detail pendaftaran.</p></div><span class="tag">${uiIcon('info')} Data demo</span></div><div class="filter-row"><div class="filter-left"><input id="enrollmentSearch" class="filter-input" placeholder="Cari siswa atau program..." oninput="filterEnrollments()"><select id="enrollmentStatus" class="filter-select" onchange="filterEnrollments()"><option value="all">Semua status</option><option>Menunggu Verifikasi</option><option>Aktif</option><option>Selesai</option><option>Ditolak</option></select></div><div class="filter-right"><button class="btn secondary sm" onclick="downloadEnrollmentsCsv()">${uiIcon('download')} Ekspor CSV</button></div></div><div id="enrollmentTable">${enrollmentTable(appState.enrollments)}</div></div><div class="notice">${uiIcon('info')} Persetujuan pendaftaran hanya simulasi lokal dan tidak mengirim notifikasi.</div>`
}
function showEnrollmentDetail(id){
  const e=appState.enrollments.find(x=>x.id===id);if(!e)return;
  const p=programById(e.programId)||{};
  openModal('Detail pendaftaran',`<div class="profile-details" style="margin-top:0"><div class="detail-box"><span>ID Pendaftaran</span><b>${esc(e.id)}</b></div><div class="detail-box"><span>Siswa</span><b>${esc(e.student)}</b></div><div class="detail-box"><span>Program</span><b>${esc(e.program)}</b></div><div class="detail-box"><span>Tanggal daftar</span><b>${esc(e.date)}</b></div><div class="detail-box"><span>Sumber</span><b>${esc(e.source||'Demo')}</b></div><div class="detail-box"><span>Status</span><b>${esc(e.status)}</b></div><div class="detail-box"><span>Progres</span><b>${Number(e.progress||0)}%</b></div><div class="detail-box"><span>Durasi program</span><b>${esc(p.duration||'—')}</b></div></div><div class="notice">${uiIcon('info')} Data pendaftaran merupakan bagian dari sesi demo.</div>`,`<button class="btn secondary" onclick="closeModal()">Tutup</button>${e.status==='Menunggu Verifikasi'?`<button class="btn btn-primary" onclick="closeModal();approveEnrollment('${e.id}')">Setujui pendaftaran</button>`:''}`)
}
function approveEnrollment(id){
  if(appState.role!=='admin'){toast('Akses terbatas','Hanya Admin Sekolah yang dapat menyetujui pendaftaran.');return}
  const e=appState.enrollments.find(x=>x.id===id);if(!e)return;
  e.status='Aktif';recordActivity('Pendaftaran disetujui',e.student+' · '+e.program);saveDemoState();closeModal();render();toast('Pendaftaran disetujui',`${e.student} kini aktif pada program ${e.program}.`)
}
function deleteEnrollment(id){
  if(appState.role!=='admin'){toast('Akses terbatas','Hanya Admin Sekolah yang dapat menghapus pendaftaran.');return}
  const e=appState.enrollments.find(x=>x.id===id);if(!e)return;
  openModal('Hapus pendaftaran?',`<p style="line-height:1.7;color:var(--muted)">Pendaftaran <b>${esc(e.student)}</b> pada program <b>${esc(e.program)}</b> akan dihapus dari sesi demo ini.</p>`,`<button class="btn secondary" onclick="closeModal()">Batal</button><button class="btn danger" onclick="confirmDeleteEnrollment('${e.id}')">Hapus</button>`)
}
function confirmDeleteEnrollment(id){
  const i=appState.enrollments.findIndex(x=>x.id===id);if(i<0)return;
  const e=appState.enrollments[i];appState.enrollments.splice(i,1);recordActivity('Pendaftaran dihapus',`${e.student} · ${e.program}`);saveDemoState();closeModal();render();toast('Pendaftaran dihapus','Data pendaftaran telah dihapus dari sesi demo.')
}
function downloadEnrollmentsCsv(){
  const csv='ID,Siswa,ID Siswa,Program,Tanggal,Sumber,Progres,Status\n'+appState.enrollments.map(e=>[e.id,e.student,e.studentId,e.program,e.date,e.source||'',e.progress,e.status].map(csvEscape).join(',')).join('\n');
  downloadFile('pendaftaran_peserta_sertikom.csv','\uFEFF'+csv,'text/csv;charset=utf-8');toast('Ekspor selesai',`${appState.enrollments.length} pendaftaran diekspor.`)
}

function invitationsPage(){
  const rows=appState.invitations;
  const registered=rows.filter(x=>x.status==='Pendaftaran masuk').length;
  const verified=rows.filter(x=>x.status==='Terverifikasi').length;
  return `${dashboardWelcome('Undangan industri','Buat tautan undangan demo dan pantau pendaftaran mitra industri.',`<button class="btn btn-primary" onclick="showInviteModal()">${uiIcon('mail')} Undang mitra</button>`)}<div class="stats-grid">${statCard('Total Undangan',String(rows.length),'✉','Tautan dibuat')}${statCard('Pendaftaran Masuk',String(registered),'◷','Menunggu persetujuan')}${statCard('Mitra Terverifikasi',String(verified),'✓','Siap berkolaborasi')}${statCard('Tautan Aktif',String(rows.filter(x=>x.status!=='Ditolak').length),'⌁','Dapat dibagikan')}</div><div class="panel"><div class="panel-head"><div><h3>Daftar undangan</h3><p>Simulasikan pendaftaran mitra dari tautan undangan.</p></div><span class="tag">${uiIcon('info')} Simulasi lokal</span></div><div class="filter-row"><div class="filter-left"><input class="filter-input" placeholder="Cari perusahaan atau email..." oninput="filterInvitations(this.value)"></div><div class="filter-right"><button class="btn secondary sm" onclick="downloadInvitationsCsv()">${uiIcon('download')} Ekspor CSV</button></div></div><div id="invitationTable">${industryTable(rows)}</div></div><div class="notice">${uiIcon('lock')} Email, tautan, dan pendaftaran tidak dikirim ke layanan eksternal.</div>`
}
function filterInvitations(q){
  const el=document.getElementById('invitationTable');if(!el)return;
  const rows=appState.invitations.filter(x=>(x.name+' '+x.email+' '+x.sector+' '+(x.contact||'')).toLowerCase().includes(String(q||'').toLowerCase()));
  el.innerHTML=rows.length?industryTable(rows):'<div class="empty"><b>Undangan tidak ditemukan</b><p>Coba kata kunci lain.</p></div>'
}
function downloadInvitationsCsv(){
  const csv='Perusahaan,Bidang,Kontak,Email,Status,Tautan\n'+appState.invitations.map(x=>[x.name,x.sector,x.contact||'',x.email,x.status||'',x.url||''].map(csvEscape).join(',')).join('\n');
  downloadFile('undangan_industri_sertikom.csv','\uFEFF'+csv,'text/csv;charset=utf-8');toast('Ekspor selesai',`${appState.invitations.length} undangan diekspor.`)
}

function certificateNumberFor(s){
  return 'SRTK-2026-'+String((s.id||'').match(/(\d+)$/)?.[1]||'001').padStart(4,'0')
}
function adminCertificatesPage(){
  const ready=appState.students.filter(s=>Number(s.score)>=75||s.cert==='Terverifikasi');
  const pending=appState.students.filter(s=>s.cert==='Diproses').length;
  const notReady=appState.students.length-ready.length;
  return `${dashboardWelcome('Sertifikat','Kelola penerbitan dan unduh sertifikat kompetensi siswa.',`<button class="btn btn-primary" onclick="navigate('certification')">${uiIcon('calendar')} Jadwal asesmen</button>`)}<div class="stats-grid">${statCard('Sertifikat Tersedia',String(ready.length),'♜','Memenuhi nilai minimum')}${statCard('Dalam Proses',String(pending),'◷','Menunggu verifikasi')}${statCard('Belum Memenuhi',String(notReady),'◴','Nilai di bawah 75')}${statCard('Total Siswa',String(appState.students.length),'♙','Data demo')}</div><div class="panel"><div class="panel-head"><div><h3>Daftar sertifikat</h3><p>Pratinjau dan cetak dokumen demo.</p></div><span class="tag">${uiIcon('shield')} Dokumen simulasi</span></div><div class="table-wrap"><table><thead><tr><th>SISWA</th><th>PROGRAM</th><th>NILAI</th><th>NOMOR</th><th>STATUS</th><th>AKSI</th></tr></thead><tbody>${appState.students.map(s=>{
    const ok=Number(s.score)>=75||s.cert==='Terverifikasi';
    const enr=appState.enrollments.find(e=>e.studentId===s.id);
    return `<tr><td><div class="user-cell"><div class="table-avatar">${initials(s.name)}</div><div><b>${esc(s.name)}</b><small>${esc(s.id)}</small></div></div></td><td>${esc(enr?.program||s.major)}</td><td><b>${Number(s.score||0)}/100</b></td><td><code>${certificateNumberFor(s)}</code></td><td><span class="status-tag ${ok?'status-success':'status-pending'}">${ok?'Tersedia':'Belum tersedia'}</span></td><td><div class="table-actions"><button class="icon-button" title="Pratinjau" onclick="showCertificatePreview('${s.id}')">${uiIcon('eye')}</button><button class="icon-button" title="Cetak" onclick="printStudentCertificate('${s.id}')" ${ok?'':'disabled'}>${uiIcon('download')}</button></div></td></tr>`
  }).join('')}</tbody></table></div></div><div class="notice">${uiIcon('info')} Sertifikat hanya dokumen simulasi dan tidak memiliki kekuatan hukum.</div>`
}
function showCertificatePreview(id){
  const s=appState.students.find(x=>x.id===id);if(!s)return;
  const ok=Number(s.score)>=75||s.cert==='Terverifikasi';
  openModal('Pratinjau sertifikat',`<div class="certificate-thumb" style="margin:0 auto"><span class="cert-thumb-logo">S</span><small>SERTIFIKAT KOMPETENSI</small><b>${esc(s.name)}</b><span>${esc(s.major)}</span><i>SERTIKOM · DEMO</i></div><div class="profile-details" style="margin-top:18px"><div class="detail-box"><span>Nomor</span><b>${certificateNumberFor(s)}</b></div><div class="detail-box"><span>Nilai</span><b>${Number(s.score||0)}/100</b></div><div class="detail-box"><span>Status</span><b>${ok?'Tersedia':'Belum tersedia'}</b></div></div>`,`<button class="btn secondary" onclick="closeModal()">Tutup</button><button class="btn btn-primary" onclick="printStudentCertificate('${s.id}')" ${ok?'':'disabled'}>Cetak / PDF</button>`)
}
function printStudentCertificate(id){
  const s=appState.students.find(x=>x.id===id);if(!s)return;
  if(Number(s.score)<75&&s.cert!=='Terverifikasi'){toast('Sertifikat belum tersedia','Nilai minimum 75 diperlukan untuk mencetak sertifikat.');return}
  const w=window.open('','_blank','width=900,height=700');if(!w){toast('Pop-up diblokir','Izinkan pop-up untuk melihat dokumen demo.');return}
  w.document.write('<!doctype html><html lang="id"><head><meta charset="utf-8"><title>Sertifikat Demo Sertikom</title><style>body{font-family:Arial,sans-serif;color:#18385f;padding:32px;background:#eaf5ff}.frame{border:8px double #1769e8;padding:45px;text-align:center;background:white;min-height:440px;border-radius:18px}small{font-size:12px;letter-spacing:3px;color:#1769e8;font-weight:bold}h1{font-size:34px;margin:24px}h2{font-size:26px;color:#1769e8;margin:12px}.name{font-size:28px;font-weight:bold;margin:26px}.note{margin-top:45px;color:#0f55c7;font-size:11px;letter-spacing:2px;font-weight:bold}@media print{body{background:white}}</style></head><body><div class="frame"><small>SERTIKOM · INDUSTRY CERTIFICATION</small><h1>SERTIFIKAT KOMPETENSI</h1><p>Diberikan kepada</p><div class="name">'+esc(s.name)+'</div><p>Atas keberhasilan menyelesaikan program</p><h2>'+esc(s.major)+'</h2><p>Nilai asesmen: <b>'+Number(s.score||0)+'/100</b></p><p>Nomor: '+certificateNumberFor(s)+'</p><div class="note">DOKUMEN SIMULASI · BUKAN SERTIFIKAT RESMI</div></div><script>window.onload=()=>window.print()<\/script></body></html>');w.document.close()
}

function settingsPage(){
  const st=appState.settings||{};
  return `${dashboardWelcome('Pengaturan','Kelola preferensi tampilan, notifikasi, dan data demo sekolah.')}<div class="settings-grid"><section class="panel"><div class="panel-head"><div><h3>Preferensi aplikasi</h3><p>Pengaturan tersimpan pada sesi browser ini.</p></div><span class="tag">${uiIcon('settings')} Demo</span></div><form id="settingsForm" class="panel-body"><label class="setting-row"><div><b>Notifikasi aktivitas</b><small>Tampilkan notifikasi untuk aktivitas demo.</small></div><input type="checkbox" name="notifications" ${st.notifications!==false?'checked':''}></label><label class="setting-row"><div><b>Simpan otomatis</b><small>Simpan perubahan state ke sessionStorage.</small></div><input type="checkbox" name="autoSave" ${st.autoSave!==false?'checked':''}></label><label class="setting-row"><div><b>Profil publik</b><small>Izinkan industri melihat profil kompetensi.</small></div><input type="checkbox" name="publicProfile" ${st.publicProfile!==false?'checked':''}></label><label class="setting-row"><div><b>Tampilan ringkas</b><small>Kurangi jarak antar komponen pada dashboard.</small></div><input type="checkbox" name="compact" ${st.compact?'checked':''}></label><div class="form-actions"><button type="button" class="btn btn-primary" onclick="saveSettings()">${uiIcon('check')} Simpan pengaturan</button><button type="button" class="btn btn-outline" onclick="showPasswordModal()">Ubah password</button></div></form></section><section class="panel"><div class="panel-head"><div><h3>Data demo</h3><p>Kembalikan seluruh data ke kondisi awal.</p></div></div><div class="panel-body"><div class="notice notice-warm">${uiIcon('info')} Reset akan menghapus perubahan siswa, guru, program, pendaftaran, dan pengaturan pada sesi ini.</div><button class="btn danger btn-block" onclick="showResetModal()">${uiIcon('refresh')} Reset data demo</button><div class="divider"></div><button class="btn btn-outline btn-block" onclick="navigate('profile')">${uiIcon('building')} Buka profil sekolah</button></div></section></div>`
}
function saveSettings(){
  const f=document.getElementById('settingsForm');if(!f)return;
  const d=new FormData(f);appState.settings={notifications:d.has('notifications'),autoSave:d.has('autoSave'),publicProfile:d.has('publicProfile'),compact:d.has('compact')};
  saveDemoState();document.body.classList.toggle('compact-ui',appState.settings.compact);render();toast('Pengaturan disimpan','Preferensi demo diperbarui pada sesi ini.')
}

function deleteStudent(id){
  if(appState.role!=='admin'){toast('Akses terbatas','Hanya Admin Sekolah yang dapat menghapus siswa.');return}
  const s=appState.students.find(x=>x.id===id);if(!s)return;
  openModal('Hapus siswa?',`<p style="line-height:1.7;color:var(--muted)">Data <b>${esc(s.name)}</b> beserta pendaftaran dan submission terkait akan dihapus dari sesi demo.</p>`,`<button class="btn secondary" onclick="closeModal()">Batal</button><button class="btn danger" onclick="confirmDeleteStudent('${s.id}')">Hapus siswa</button>`)
}
function confirmDeleteStudent(id){
  const i=appState.students.findIndex(x=>x.id===id);if(i<0)return;
  const s=appState.students[i];appState.students.splice(i,1);appState.enrollments=appState.enrollments.filter(e=>e.studentId!==id);appState.submissions=appState.submissions.filter(x=>x.studentId!==id);recordActivity('Siswa dihapus',s.name);saveDemoState();closeModal();render();toast('Siswa dihapus',`${s.name} telah dihapus dari data demo.`)
}
function deleteTeacher(id){
  if(appState.role!=='admin'){toast('Akses terbatas','Hanya Admin Sekolah yang dapat menghapus guru.');return}
  const t=appState.teachers.find(x=>x.id===id);if(!t)return;
  openModal('Hapus guru?',`<p style="line-height:1.7;color:var(--muted)">Data guru <b>${esc(t.name)}</b> akan dihapus dari sesi demo.</p>`,`<button class="btn secondary" onclick="closeModal()">Batal</button><button class="btn danger" onclick="confirmDeleteTeacher('${t.id}')">Hapus guru</button>`)
}
function confirmDeleteTeacher(id){
  const i=appState.teachers.findIndex(x=>x.id===id);if(i<0)return;
  const t=appState.teachers[i];appState.teachers.splice(i,1);recordActivity('Guru dihapus',t.name);saveDemoState();closeModal();render();toast('Guru dihapus',`${t.name} telah dihapus dari data demo.`)
}
function deleteProgram(id){
  if(appState.role!=='admin'){toast('Akses terbatas','Hanya Admin Sekolah yang dapat menghapus program.');return}
  const p=programById(id);if(!p)return;
  const used=appState.enrollments.some(e=>e.programId===id);
  openModal('Hapus program?',`<p style="line-height:1.7;color:var(--muted)">Program <b>${esc(p.title)}</b> akan dihapus dari katalog demo.${used?' <b>Program ini masih memiliki pendaftar.</b>':''}</p>`,`<button class="btn secondary" onclick="closeModal()">Batal</button><button class="btn danger" onclick="confirmDeleteProgram('${p.id}')">Hapus program</button>`)
}
function confirmDeleteProgram(id){
  const i=appState.programs.findIndex(x=>x.id===id);if(i<0)return;
  const p=appState.programs[i];appState.programs.splice(i,1);appState.enrollments=appState.enrollments.filter(e=>e.programId!==id);recordActivity('Program dihapus',p.title);saveDemoState();closeModal();render();toast('Program dihapus',`${p.title} telah dihapus dari katalog demo.`)
}
